with src as (select * from subscriptions where plan = 'premium' and start_date between '2023-03-29' and '2025-03-01'), summary as (select case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end as start_cohort, round(avg(monthly_fee), 2) as avg_monthly_fee from src group by case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end) select * from summary where avg_monthly_fee < 29 order by avg_monthly_fee desc, start_cohort limit 50
